package semester1.practice04.homework;

import java.util.Scanner;

final class Homework04 {
    private Homework04() { }
    static void run(int task){ semester1.ConsoleOutput.useUtf8();try(Scanner s=new Scanner(System.in)){switch(task){case 1->range(s);case 2->digits(s);case 3->fibonacci(s);case 4->primes(s);case 5->battle(s);default->throw new IllegalArgumentException();}}}
    private static int read(Scanner s,String p){System.out.print(p);while(!s.hasNextInt()){System.out.println("Введіть ціле число.");s.next();System.out.print(p);}return s.nextInt();}
    private static void range(Scanner s){int n;do{n=read(s,"N (>0): ");if(n<=0)System.out.println("N має бути додатним.");}while(n<=0);long sum=0,even=0,odd=0;int ce=0,co=0;for(int i=1;i<=n;i++){sum+=i;if(i%2==0){even+=i;ce++;}else{odd+=i;co++;}}System.out.printf("Сума: %d%nПарні: %d (кількість %d)%nНепарні: %d (кількість %d)%nСереднє: %.2f%n",sum,even,ce,odd,co,(double)sum/n);}
    private static void digits(Scanner s){int original;do{original=read(s,"Додатне число: ");}while(original<=0);int temp=original,rev=0,sum=0,count=0,max=0;while(temp>0){int digit=temp%10;rev=rev*10+digit;sum+=digit;max=Math.max(max,digit);count++;temp/=10;}System.out.printf("Число %d: цифр %d, сума %d, найбільша %d, реверс %d.%n%s%n",original,count,sum,max,rev,original==rev?"Паліндром!":"Звичайне число.");}
    private static void fibonacci(Scanner s){int n;do{n=read(s,"Скільки чисел Фібоначчі (3–46): ");}while(n<3||n>46);int a=1,b=1;System.out.println("№1: 1\n№2: 1");double ratio=1;for(int k=3;k<=n;k++){int next=a+b;ratio=(double)next/b;System.out.printf("№%d: %d | відношення %.6f%n",k,next,ratio);a=b;b=next;}System.out.printf("Наближення φ: %.6f (еталон 1.618034)%n",ratio);}
    private static void primes(Scanner s){int n;do{n=read(s,"Верхня межа N (2–100000): ");}while(n<2||n>100000);int count=0;long sum=0;StringBuilder list=new StringBuilder();for(int x=2;x<=n;x++){boolean prime=true;for(int d=2;d<=x/d;d++)if(x%d==0){prime=false;break;}if(prime){if(!list.isEmpty())list.append(", ");list.append(x);sum+=x;count++;}}System.out.println("Прості числа: "+list);int total=n-1;System.out.printf("Кількість: %d%nСума: %d%nЧастка: %.2f%%%n",count,sum,100.0*count/total);}
    private static void battle(Scanner s){System.out.println("Обери бійця: 1 Шеллі, 2 Кольт, 3 Ель Прімо");int pick=read(s,"Твій вибір: ");String name;int hp,maxHp,attack,superAttack;switch(pick){case 1->{name="Шеллі";hp=maxHp=4000;attack=1200;superAttack=2800;}case 2->{name="Кольт";hp=maxHp=3000;attack=1600;superAttack=3600;}default->{name="Ель Прімо";hp=maxHp=6000;attack=1100;superAttack=2200;}}int boss=10000,ammo=3,charge=0,round=0;double boost=1;boolean knock=false,stun=false;while(hp>0&&boss>0&&round<100){round++;int bars=(int)(10.0*boss/10000);System.out.printf("Раунд %d | %s %d/%d HP | Boss %d/10000 [",round,name,hp,maxHp,boss);for(int b=0;b<10;b++)System.out.print(b<bars?'█':'░');System.out.println("]");int action=read(s,"1 атака, 2 супер, 3 захист, 4 куб: ");switch(action){case 1->{if(ammo>0){boss-=Math.min(boss,(int)(attack*boost));ammo--;charge=Math.min(100,charge+35);System.out.println(name+" атакує!");}else System.out.println("Немає набоїв — перезарядка.");}case 2->{if(charge>=100){boss-=Math.min(boss,(int)(superAttack*boost));charge=0;if(pick==1)knock=true;if(pick==3)stun=true;}else System.out.println("Супер ще не заряджений.");}case 3->{ammo=Math.min(3,ammo+2);hp=Math.min(maxHp,hp+(int)(maxHp*.15));}case 4->{if(Math.random()<.6){boost+=.15;System.out.println("Power Cube! Шкода +15%.");}else System.out.println("Куб не знайшовся.");}default->System.out.println("Хід втрачено.");}if(boss>0&&stun){System.out.println("Бос оглушений.");stun=false;}else if(boss>0){double fraction=boss/10000.0;int damage=fraction>.6?700:fraction>=.3?(int)(700*1.3):(int)(700*1.7);if(knock){damage/=2;knock=false;}if(Math.random()<.15)System.out.println("Ухилення!");else hp-=damage;}ammo=Math.min(3,ammo+1);}if(boss<=0)System.out.printf("Перемога за %d раундів! +10 трофеїв, 100 Starr Drops.%n",round);else System.out.println("Поразка. Сейф зруйновано; спробуй витривалішого бійця!");}
}
